def analyze(inp,H,W,outg):
    seps=[]
    for s in set(v for r in inp for v in r):
        if any(all(r[j]==s for j in range(W)) for r in inp) or any(all(inp[i][j]==s for i in range(H)) for j in range(W)):
            seps.append(s)
    print("seps:",seps)
    rs=[i for i in range(H) if all(inp[i][j]==seps[0] for j in range(W))]
    cs=[j for j in range(W) if all(inp[i][j]==seps[0] for i in range(H))]
    rbands=[range(st,en) for st,en in zip([0]+rs,sorted(rs+[H]))]
    cbands=[range(st,en) for st,en in zip([0]+cs,sorted(cs+[W]))]
    out=[]
    for ri,rb in enumerate(rbands):
        for ci,cb in enumerate(cbands):
            cnt=C.Counter(); 
            for rr in rb:
                for cc in cb: cnt[inp[rr][cc]]+=1
            bgs=[k for k,v in cnt.items() if k!=seps[0]]
            mx=max(cnt[b] for b in bgs); mn=min(cnt[b] for b in bgs)
            nc=sum(cnt[b] for b in bgs)-mx
            exp=outg[ri][ci]
            out.append((ri,ci,dict(cnt),bgs,mx,mn,nc,exp))
    return out

